def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build grid, 1-indexed
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    INF = -10**18
    # dp[x1][x2] where x1, x2 are row indices of two walkers at same step
    dp = [[INF] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]

    # total steps from start to finish (excluding start step 0)
    total_steps = 2 * N - 2
    for step in range(1, total_steps + 1):
        dp_next = [[INF] * (N + 1) for _ in range(N + 1)]
        for x1 in range(1, N + 1):
            y1 = step - (x1 - 1) + 1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(1, N + 1):
                y2 = step - (x2 - 1) + 1
                if y2 < 1 or y2 > N:
                    continue
                # Compute best previous move
                best_prev = INF
                for dx1 in (-1, 0):  # came from up (dx1=-1) or left (dx1=0)
                    px1 = x1 + dx1
                    if px1 < 1 or px1 > N:
                        continue
                    for dx2 in (-1, 0):
                        px2 = x2 + dx2
                        if px2 < 1 or px2 > N:
                            continue
                        best_prev = max(best_prev, dp[px1][px2])
                if best_prev == INF:
                    continue
                add_val = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add_val += grid[x2][y2]
                dp_next[x1][x2] = best_prev + add_val
        dp = dp_next

    return dp[N][N]

