            coeff_part = ""
        else:
            coeff_part = str(abs_coeff)

        # Determine the variable part
        if degree == 0:
            var_part = ""
        elif degree == 1:
            var_part = "x"
        else:
            var_part = f"x^{degree}"

        term = f"{sign}{coeff_part}{var_part}"
        pieces.append(term)
        first_term = False

    if not pieces:
        return "0"

    return "".join(pieces)

