    """
    # Helper to evaluate the truth value of a single statement
    def evaluate_statement(name: str, stmt: str, guilty: str) -> bool | None:
        stmt = stmt.strip()
        # Ignore statements about the day of the week
        upper_stmt = stmt.upper()
        if any(day in upper_stmt for day in days_of_week):
            return None
        # Remove final period if present
        if stmt.endswith('.'):
            stmt = stmt[:-1]
        # Check patterns
        if stmt.lower().startswith("i am guilty"):
            return name == guilty
        if stmt.lower().startswith("i am not guilty"):
            return name != guilty
        # Generic form: "<TARGET> is guilty" or "<TARGET> is not guilty"
