        if len(parts) >= 3 and parts[1].lower() == "is":
            target = parts[0]
            if parts[-1].lower() == "guilty":
                if len(parts) >= 4 and parts[2].lower() == "not":
                    # "<TARGET> is not guilty"
                    return guilty != target
                else:
                    # "<TARGET> is guilty"
                    return guilty == target
        # Unrecognised statement format
        return None

    for name, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate_statement(name, stmt, scenario)
            if truth is None:
                continue
            if name in liar_count:
                # Liars must utter false statements
                if truth:
                    return False
            else:
                # Truth-tellers must utter true statements
                if not truth:
                    return False
    return True

